import{_ as r,C as o,o as e,c as p,a2 as n,b as i,w as a,a as d,E as s,a3 as E}from"./chunks/framework.DIWxYxwh.js";const D=JSON.parse('{"title":"机器人运动控制与电机驱动架构","description":"","frontmatter":{},"headers":[],"relativePath":"具身智能/机器人运动控制与电机驱动架构.md","filePath":"具身智能/机器人运动控制与电机驱动架构.md","lastUpdated":null}'),A={name:"具身智能/机器人运动控制与电机驱动架构.md"};function c(h,t,B,_,C,b){const l=o("Mermaid");return e(),p("div",null,[t[3]||(t[3]=n('<h1 id="机器人运动控制与电机驱动架构" tabindex="-1">机器人运动控制与电机驱动架构 <a class="header-anchor" href="#机器人运动控制与电机驱动架构" aria-label="Permalink to &quot;机器人运动控制与电机驱动架构&quot;">​</a></h1><h2 id="_1-文档概述" tabindex="-1">1. 文档概述 <a class="header-anchor" href="#_1-文档概述" aria-label="Permalink to &quot;1. 文档概述&quot;">​</a></h2><h3 id="_1-1-文档目的" tabindex="-1">1.1 文档目的 <a class="header-anchor" href="#_1-1-文档目的" aria-label="Permalink to &quot;1.1 文档目的&quot;">​</a></h3><p>本文介绍机器人从上层动作请求到伺服电机执行的完整控制架构，重点说明运动控制、轨迹规划、关节与电机映射、CANopen 通信、CiA 402 驱动器状态机、CSP 周期同步位置控制及状态反馈之间的关系。</p><p>通过分层设计，将上层运动需求转换为驱动器能够执行的位置指令，并通过状态反馈、异常检测和安全停止机制形成完整的控制闭环。</p><h3 id="_1-2-设计目标" tabindex="-1">1.2 设计目标 <a class="header-anchor" href="#_1-2-设计目标" aria-label="Permalink to &quot;1.2 设计目标&quot;">​</a></h3><ul><li><strong>统一控制入口</strong>：通过电机控制 API 向底层设备发送控制请求。</li><li><strong>解耦运动规划与硬件实现</strong>：轨迹规划不直接依赖 CAN 报文或具体通信设备。</li><li><strong>统一数据转换</strong>：明确关节角度、电机旋转量及驱动器位置单位之间的转换关系。</li><li><strong>支持周期位置控制</strong>：通过 CANopen PDO 等机制向支持 CSP 的驱动器更新目标位置。</li><li><strong>完善状态反馈</strong>：监测实际位置、驱动器状态、通信异常及动作执行结果。</li><li><strong>明确安全边界</strong>：区分普通软件停止、驱动器快速停止与独立安全功能。</li></ul><h3 id="_1-3-适用范围" tabindex="-1">1.3 适用范围 <a class="header-anchor" href="#_1-3-适用范围" aria-label="Permalink to &quot;1.3 适用范围&quot;">​</a></h3><p>本文覆盖以下技术层次：</p><ol><li>上层动作请求与运动控制。</li><li>轨迹规划与关节运动学映射。</li><li>电机控制 API 与协议库。</li><li>CANable、SocketCAN 与 CAN 总线。</li><li>CANopen 通信及 CiA 402 驱动器控制。</li><li>CSP 位置执行、状态反馈与故障处理。</li></ol><p>文中涉及的具体接口和配置以当前项目描述为依据。对象字典、PDO 映射、驱动器位置单位及安全功能的实际配置，应以设备手册和项目源码为准。</p><hr><h2 id="_2-系统总体架构" tabindex="-1">2. 系统总体架构 <a class="header-anchor" href="#_2-系统总体架构" aria-label="Permalink to &quot;2. 系统总体架构&quot;">​</a></h2><h3 id="_2-1-架构分层" tabindex="-1">2.1 架构分层 <a class="header-anchor" href="#_2-1-架构分层" aria-label="Permalink to &quot;2.1 架构分层&quot;">​</a></h3><p>系统采用分层控制架构，将上层动作决策、运动规划、设备控制、通信协议和硬件执行分离。</p>',15)),(e(),i(E,null,{default:a(()=>[s(l,{id:"mermaid-101",class:"mermaid",graph:"flowchart%20TB%0A%20%20%20%20A%5B%22Agent%20%2F%20Skill%3Cbr%2F%3E%E4%B8%8A%E5%B1%82%E5%8A%A8%E4%BD%9C%E8%AF%B7%E6%B1%82%22%5D%0A%20%20%20%20B%5B%22head_service%20%2F%20motor_control%3Cbr%2F%3E%E5%8A%A8%E4%BD%9C%E7%AE%A1%E7%90%86%E4%B8%8E%E8%BF%90%E5%8A%A8%E6%8E%A7%E5%88%B6%22%5D%0A%20%20%20%20C%5B%22%E8%BD%A8%E8%BF%B9%E8%A7%84%E5%88%92%E6%A8%A1%E5%9D%97%3Cbr%2F%3E%E4%BD%8D%E7%BD%AE%E3%80%81%E9%80%9F%E5%BA%A6%E3%80%81%E5%8A%A0%E9%80%9F%E5%BA%A6%E7%BA%A6%E6%9D%9F%22%5D%0A%20%20%20%20D%5B%22%E5%85%B3%E8%8A%82%E4%B8%8E%E7%94%B5%E6%9C%BA%E6%98%A0%E5%B0%84%3Cbr%2F%3E%E8%A7%92%E5%BA%A6%E3%80%81%E5%87%8F%E9%80%9F%E6%AF%94%E3%80%81%E4%BD%8D%E7%BD%AE%E5%8D%95%E4%BD%8D%E8%BD%AC%E6%8D%A2%22%5D%0A%20%20%20%20E%5B%22servo_motor_api.c%3Cbr%2F%3E%E7%BB%9F%E4%B8%80%E7%94%B5%E6%9C%BA%E6%8E%A7%E5%88%B6%20API%22%5D%0A%20%20%20%20F%5B%22libeu_harmonic.so%3Cbr%2F%3ECANopen%20%E5%8D%8F%E8%AE%AE%E4%B8%8E%E9%A9%B1%E5%8A%A8%E5%99%A8%E6%8E%A7%E5%88%B6%22%5D%0A%20%20%20%20G%5B%22libeu_canable.so%3Cbr%2F%3ECANable%20%E8%AE%BE%E5%A4%87%E9%80%9A%E4%BF%A1%E5%90%8E%E7%AB%AF%22%5D%0A%20%20%20%20H%5B%22SocketCAN%3Cbr%2F%3ELinux%20canX%20%E6%8E%A5%E5%8F%A3%22%5D%0A%20%20%20%20I%5B%22CANable%20USB-CAN%22%5D%0A%20%20%20%20J%5B%22CAN%20%E6%80%BB%E7%BA%BF%22%5D%0A%20%20%20%20K%5B%22CANopen%20%E4%BC%BA%E6%9C%8D%E9%A9%B1%E5%8A%A8%E5%99%A8%3Cbr%2F%3ECiA%20402%20%2F%20CSP%22%5D%0A%20%20%20%20L%5B%22%E7%94%B5%E6%9C%BA%E4%B8%8E%E6%9C%BA%E6%A2%B0%E5%85%B3%E8%8A%82%22%5D%0A%0A%20%20%20%20A%20--%3E%20B%20--%3E%20C%20--%3E%20D%20--%3E%20E%20--%3E%20F%20--%3E%20G%20--%3E%20H%20--%3E%20I%20--%3E%20J%20--%3E%20K%20--%3E%20L%0A%20%20%20%20L%20-.%20%22%E5%AE%9E%E9%99%85%E8%BF%90%E5%8A%A8%E5%8F%8D%E9%A6%88%22%20.-%3E%20K%0A%20%20%20%20K%20-.%20%22%E4%BD%8D%E7%BD%AE%E3%80%81%E7%8A%B6%E6%80%81%E3%80%81%E6%95%85%E9%9A%9C%E5%8F%8D%E9%A6%88%22%20.-%3E%20J%0A%20%20%20%20J%20-.-%3E%20I%0A%20%20%20%20I%20-.-%3E%20H%0A%20%20%20%20H%20-.-%3E%20G%0A%20%20%20%20G%20-.-%3E%20F%0A%20%20%20%20F%20-.-%3E%20E%0A%20%20%20%20E%20-.-%3E%20B%0A%0A%20%20%20%20classDef%20control%20fill%3A%23E8F1FC%2Cstroke%3A%234978A8%2Ccolor%3A%23172B4D%0A%20%20%20%20classDef%20communication%20fill%3A%23EAF5EA%2Cstroke%3A%2354865A%2Ccolor%3A%23183B20%0A%20%20%20%20classDef%20hardware%20fill%3A%23FFF1DE%2Cstroke%3A%23B8833E%2Ccolor%3A%23593A13%0A%0A%20%20%20%20class%20A%2CB%2CC%2CD%20control%0A%20%20%20%20class%20E%2CF%2CG%2CH%20communication%0A%20%20%20%20class%20I%2CJ%2CK%2CL%20hardware%0A"})]),fallback:a(()=>[...t[0]||(t[0]=[d(" Loading... ",-1)])]),_:1})),t[4]||(t[4]=n('<p>图中实线表示主要指令链路，虚线表示反馈链路。反馈路径用于上层判断运动状态和执行结果；实际系统中，各层的调用方式可能是同步调用、周期任务或独立线程，具体以代码实现为准。</p><h3 id="_2-2-各模块职责" tabindex="-1">2.2 各模块职责 <a class="header-anchor" href="#_2-2-各模块职责" aria-label="Permalink to &quot;2.2 各模块职责&quot;">​</a></h3><table tabindex="0"><thead><tr><th>模块</th><th>核心职责</th><th>不应承担的职责</th></tr></thead><tbody><tr><td>Agent / Skill</td><td>生成动作请求及目标参数</td><td>直接操作 CAN 总线</td></tr><tr><td><code>head_service / motor_control</code></td><td>管理动作生命周期、执行状态及异常处理</td><td>实现底层 CAN 报文细节</td></tr><tr><td>轨迹规划模块</td><td>生成满足运动约束的目标轨迹</td><td>管理 USB-CAN 设备</td></tr><tr><td>关节与电机映射模块</td><td>进行关节角度、电机位置和驱动器单位换算</td><td>负责通信状态机</td></tr><tr><td><code>servo_motor_api.c</code></td><td>提供统一的电机控制接口</td><td>直接承担上层动作决策</td></tr><tr><td><code>libeu_harmonic.so</code></td><td>处理 CANopen 指令、驱动器控制及状态解析</td><td>决定上层动作语义</td></tr><tr><td><code>libeu_canable.so</code></td><td>对接 CANable 设备及 SocketCAN 通信</td><td>实现完整运动规划</td></tr><tr><td>伺服驱动器</td><td>根据设定模式执行底层运动控制</td><td>替代上层动作管理与协调</td></tr></tbody></table><p><strong>架构原则：</strong> 上层模块负责决定“运动到哪里、如何运动、何时结束”；底层协议模块负责“如何与驱动器通信”；驱动器负责“如何执行位置控制”。</p><hr><h2 id="_3-运动控制与轨迹规划" tabindex="-1">3. 运动控制与轨迹规划 <a class="header-anchor" href="#_3-运动控制与轨迹规划" aria-label="Permalink to &quot;3. 运动控制与轨迹规划&quot;">​</a></h2><h3 id="_3-1-动作执行流程" tabindex="-1">3.1 动作执行流程 <a class="header-anchor" href="#_3-1-动作执行流程" aria-label="Permalink to &quot;3.1 动作执行流程&quot;">​</a></h3><p>一次完整的运动任务通常经历以下阶段：</p><ol><li><strong>接收请求</strong>：获取目标关节角度、动作时长及相关参数。</li><li><strong>参数校验</strong>：检查关节限位、参数有效性、设备可用性及驱动器状态。</li><li><strong>获取初始状态</strong>：读取实际位置、运行状态及必要的速度信息。</li><li><strong>生成轨迹</strong>：根据起始状态、目标状态和运动约束生成参考轨迹。</li><li><strong>周期更新</strong>：根据轨迹时间计算当前周期的目标位置。</li><li><strong>坐标映射</strong>：将关节目标转换为电机或驱动器使用的位置单位。</li><li><strong>发送指令</strong>：通过电机控制 API 和 CANopen 通信链路发送目标。</li><li><strong>监测反馈</strong>：读取实际位置、驱动器状态及故障信息。</li><li><strong>判断完成</strong>：根据位置误差、运动状态、稳定时间和超时条件判断结果。</li><li><strong>结束任务</strong>：返回成功、失败、取消或超时等执行结果。</li></ol><h3 id="_3-2-动作控制流程图" tabindex="-1">3.2 动作控制流程图 <a class="header-anchor" href="#_3-2-动作控制流程图" aria-label="Permalink to &quot;3.2 动作控制流程图&quot;">​</a></h3>',10)),(e(),i(E,null,{default:a(()=>[s(l,{id:"mermaid-281",class:"mermaid",graph:"flowchart%20TD%0A%20%20%20%20A%5B%22%E6%8E%A5%E6%94%B6%E5%8A%A8%E4%BD%9C%E8%AF%B7%E6%B1%82%22%5D%20--%3E%20B%5B%22%E6%A0%A1%E9%AA%8C%E5%8F%82%E6%95%B0%E4%B8%8E%E5%85%B3%E8%8A%82%E9%99%90%E4%BD%8D%22%5D%0A%20%20%20%20B%20--%3E%20C%7B%22%E5%8F%82%E6%95%B0%E6%9C%89%E6%95%88%E4%B8%94%E8%AE%BE%E5%A4%87%E5%8F%AF%E7%94%A8%EF%BC%9F%22%7D%0A%20%20%20%20C%20--%20%E5%90%A6%20--%3E%20X%5B%22%E6%8B%92%E7%BB%9D%E6%89%A7%E8%A1%8C%E5%B9%B6%E8%BF%94%E5%9B%9E%E5%8E%9F%E5%9B%A0%22%5D%0A%20%20%20%20C%20--%20%E6%98%AF%20--%3E%20D%5B%22%E8%AF%BB%E5%8F%96%E5%BD%93%E5%89%8D%E4%BD%8D%E7%BD%AE%E4%B8%8E%E9%A9%B1%E5%8A%A8%E5%99%A8%E7%8A%B6%E6%80%81%22%5D%0A%20%20%20%20D%20--%3E%20E%7B%22%E9%A9%B1%E5%8A%A8%E5%99%A8%E5%85%81%E8%AE%B8%E8%BF%90%E5%8A%A8%EF%BC%9F%22%7D%0A%20%20%20%20E%20--%20%E5%90%A6%20--%3E%20Y%5B%22%E8%BF%9B%E5%85%A5%E6%95%85%E9%9A%9C%E6%88%96%E6%9C%AA%E5%B0%B1%E7%BB%AA%E5%A4%84%E7%90%86%22%5D%0A%20%20%20%20E%20--%20%E6%98%AF%20--%3E%20F%5B%22%E7%94%9F%E6%88%90%E8%BF%90%E5%8A%A8%E8%BD%A8%E8%BF%B9%22%5D%0A%20%20%20%20F%20--%3E%20G%5B%22%E8%AE%A1%E7%AE%97%E5%BD%93%E5%89%8D%E5%91%A8%E6%9C%9F%E7%9B%AE%E6%A0%87%E4%BD%8D%E7%BD%AE%22%5D%0A%20%20%20%20G%20--%3E%20H%5B%22%E5%85%B3%E8%8A%82%E6%98%A0%E5%B0%84%E4%B8%8E%E5%8D%95%E4%BD%8D%E8%BD%AC%E6%8D%A2%22%5D%0A%20%20%20%20H%20--%3E%20I%5B%22%E5%8F%91%E9%80%81%E7%94%B5%E6%9C%BA%E7%9B%AE%E6%A0%87%E6%8C%87%E4%BB%A4%22%5D%0A%20%20%20%20I%20--%3E%20J%5B%22%E8%AF%BB%E5%8F%96%E5%AE%9E%E9%99%85%E4%BD%8D%E7%BD%AE%E4%B8%8E%E9%A9%B1%E5%8A%A8%E5%99%A8%E7%8A%B6%E6%80%81%22%5D%0A%20%20%20%20J%20--%3E%20K%7B%22%E5%8F%91%E7%94%9F%E6%95%85%E9%9A%9C%E6%88%96%E8%B6%85%E6%97%B6%EF%BC%9F%22%7D%0A%20%20%20%20K%20--%20%E6%98%AF%20--%3E%20Y%0A%20%20%20%20K%20--%20%E5%90%A6%20--%3E%20L%7B%22%E6%BB%A1%E8%B6%B3%E5%AE%8C%E6%88%90%E6%9D%A1%E4%BB%B6%EF%BC%9F%22%7D%0A%20%20%20%20L%20--%20%E5%90%A6%20--%3E%20G%0A%20%20%20%20L%20--%20%E6%98%AF%20--%3E%20M%5B%22%E8%AE%B0%E5%BD%95%E7%BB%93%E6%9E%9C%E5%B9%B6%E7%BB%93%E6%9D%9F%E4%BB%BB%E5%8A%A1%22%5D%0A"})]),fallback:a(()=>[...t[1]||(t[1]=[d(" Loading... ",-1)])]),_:1})),t[5]||(t[5]=n(`<h3 id="_3-3-五次多项式轨迹" tabindex="-1">3.3 五次多项式轨迹 <a class="header-anchor" href="#_3-3-五次多项式轨迹" aria-label="Permalink to &quot;3.3 五次多项式轨迹&quot;">​</a></h3><p>对于起始位置为 $q_0$、目标位置为 $q_f$、持续时间为 $T$，且起止速度和加速度均为零的单段运动，可以采用五次多项式进行插值。</p><p>定义归一化时间：</p><p>$$ s=\\operatorname{clamp}\\left(\\frac{t}{T},0,1\\right) $$</p><p>目标位置为：</p><p>$$ q(t)=q_0+(q_f-q_0)(10s^3-15s^4+6s^5) $$</p><p>其中：</p><ul><li>$q_0$：起始位置。</li><li>$q_f$：目标位置。</li><li>$T$：轨迹持续时间。</li><li>$t$：当前轨迹时间。</li><li>$s$：归一化时间，范围为 0 到 1。</li></ul><p>该轨迹在起点和终点具有零速度、零加速度，适用于平滑的位置运动。</p><p>但五次多项式并不自动保证所有设备约束均满足。生成轨迹后，仍需检查最大速度、最大加速度、最大加加速度（如有要求）、关节限位及机械干涉。</p><p>对于点头、摆动等复合动作，应将动作拆分为多个阶段，并明确每个阶段的目标位置、持续时间、衔接条件及多轴同步要求。</p><h3 id="_3-4-控制周期的区别" tabindex="-1">3.4 控制周期的区别 <a class="header-anchor" href="#_3-4-控制周期的区别" aria-label="Permalink to &quot;3.4 控制周期的区别&quot;">​</a></h3><p>系统中存在多个不同的时间尺度：</p><table tabindex="0"><thead><tr><th>时间尺度</th><th>含义</th></tr></thead><tbody><tr><td>动作持续时间</td><td>一次动作从开始到目标状态的计划时长</td></tr><tr><td>轨迹更新周期</td><td>控制器重新计算参考轨迹的时间间隔</td></tr><tr><td>通信发送周期</td><td>控制器发送目标位置或过程数据的时间间隔</td></tr><tr><td>驱动器内部控制周期</td><td>驱动器内部位置、速度和电流控制的执行周期</td></tr></tbody></table><p>这些周期不一定相同。特别是在 CSP 模式下，主站更新目标位置的周期必须与驱动器配置、PDO 通信机制和系统实时性要求相匹配。</p><hr><h2 id="_4-关节与电机位置映射" tabindex="-1">4. 关节与电机位置映射 <a class="header-anchor" href="#_4-关节与电机位置映射" aria-label="Permalink to &quot;4. 关节与电机位置映射&quot;">​</a></h2><h3 id="_4-1-减速比换算" tabindex="-1">4.1 减速比换算 <a class="header-anchor" href="#_4-1-减速比换算" aria-label="Permalink to &quot;4.1 减速比换算&quot;">​</a></h3><p>定义减速比：</p><p>$$ R=\\frac{\\text{电机转速}}{\\text{关节输出转速}} $$</p><p>在忽略零点偏移、传动方向及机械误差时，电机旋转圈数与关节角度之间的关系为：</p><p>$$ N_{\\text{motor}}=\\frac{\\theta_{\\text{joint}}R}{360} $$</p><p>反向转换为：</p><p>$$ \\theta_{\\text{joint}}=\\frac{360N_{\\text{motor}}}{R} $$</p><p>其中：</p><ul><li>$\\theta_{\\text{joint}}$：关节角度，单位为度。</li><li>$N_{\\text{motor}}$：电机旋转圈数。</li><li>$R$：减速比。</li></ul><p><strong>示例：</strong> 减速比为 50:1，关节目标旋转 30°，则电机需要旋转：</p><p>$$ N_{\\text{motor}}=\\frac{30\\times50}{360} \\approx4.1667\\text{ 转} $$</p><p>该结果是理想传动关系下的换算值，不包含实际零点偏移及机械误差。</p><h3 id="_4-2-编码器计数换算" tabindex="-1">4.2 编码器计数换算 <a class="header-anchor" href="#_4-2-编码器计数换算" aria-label="Permalink to &quot;4.2 编码器计数换算&quot;">​</a></h3><p>若每个电机转对应 $C$ 个有效位置计数，则：</p><p>$$ \\theta_{\\text{joint}}= \\frac{360\\times\\text{count}}{C\\times R} $$</p><p>该公式仅适用于已明确计数定义、零点和方向的情况。</p><p>实际系统需要确认：</p><ul><li>编码器每转计数与驱动器位置单位的定义。</li><li>编码器计数是否包含四倍频、电子齿轮或其他倍率。</li><li>电机零点、关节零点及方向约定。</li><li>单圈或多圈位置的表示方式。</li><li>机械减速比与驱动器内部换算参数。</li></ul><h3 id="_4-3-推荐的映射接口" tabindex="-1">4.3 推荐的映射接口 <a class="header-anchor" href="#_4-3-推荐的映射接口" aria-label="Permalink to &quot;4.3 推荐的映射接口&quot;">​</a></h3><p>建议将关节映射集中封装为独立模块，避免在运动控制逻辑和协议代码中重复计算。</p><p>逻辑接口示例：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>joint_to_motor_position(joint_position)</span></span>
<span class="line"><span>    -&gt; motor_position</span></span>
<span class="line"><span></span></span>
<span class="line"><span>motor_to_joint_position(motor_position)</span></span>
<span class="line"><span>    -&gt; joint_position</span></span></code></pre></div><p>映射模块应统一处理减速比、方向、零点偏移及驱动器位置单位。若系统包含非线性传动或多关节耦合，还需使用对应的运动学模型，而不能仅依靠简单减速比换算。</p><hr><h2 id="_5-canopen-通信与驱动器控制" tabindex="-1">5. CANopen 通信与驱动器控制 <a class="header-anchor" href="#_5-canopen-通信与驱动器控制" aria-label="Permalink to &quot;5. CANopen 通信与驱动器控制&quot;">​</a></h2><h3 id="_5-1-通信硬件与软件链路" tabindex="-1">5.1 通信硬件与软件链路 <a class="header-anchor" href="#_5-1-通信硬件与软件链路" aria-label="Permalink to &quot;5.1 通信硬件与软件链路&quot;">​</a></h3><p>当前通信链路为：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>servo_motor_api.c</span></span>
<span class="line"><span>       |</span></span>
<span class="line"><span>       v</span></span>
<span class="line"><span>libeu_harmonic.so</span></span>
<span class="line"><span>       |</span></span>
<span class="line"><span>       v</span></span>
<span class="line"><span>libeu_canable.so</span></span>
<span class="line"><span>       |</span></span>
<span class="line"><span>       v</span></span>
<span class="line"><span>Linux SocketCAN（canX）</span></span>
<span class="line"><span>       |</span></span>
<span class="line"><span>       v</span></span>
<span class="line"><span>CANable USB-CAN</span></span>
<span class="line"><span>       |</span></span>
<span class="line"><span>       v</span></span>
<span class="line"><span>CAN 总线</span></span>
<span class="line"><span>       |</span></span>
<span class="line"><span>       v</span></span>
<span class="line"><span>CANopen 伺服驱动器</span></span></code></pre></div><p>其中：</p><ul><li><code>servo_motor_api.c</code>：上层电机控制入口。</li><li><code>libeu_harmonic.so</code>：处理 CANopen 指令、驱动器控制及反馈解析。</li><li><code>libeu_canable.so</code>：提供 CANable 设备通信后端。</li><li>SocketCAN：Linux CAN 通信接口。</li><li>CANable：连接主机与 CAN 总线的 USB-CAN 设备。</li></ul><h3 id="_5-2-初始化配置" tabindex="-1">5.2 初始化配置 <a class="header-anchor" href="#_5-2-初始化配置" aria-label="Permalink to &quot;5.2 初始化配置&quot;">​</a></h3><p>当前初始化接口为：</p><div class="language-c vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">c</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">harmonic_initDLL</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    harmonic_DeviceType_Canable,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    devIndex_0,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    harmonic_Baudrate_1000</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span></code></pre></div><p>当前配置如下：</p><table tabindex="0"><thead><tr><th>配置项</th><th>当前值</th><th>说明</th></tr></thead><tbody><tr><td>设备类型</td><td><code>harmonic_DeviceType_Canable</code></td><td>使用 CANable 设备后端</td></tr><tr><td>设备索引</td><td><code>devIndex_0 = 1</code></td><td>具体含义由设备库实现决定</td></tr><tr><td>CAN 波特率</td><td><code>harmonic_Baudrate_1000</code></td><td>对应 1 Mbps</td></tr></tbody></table><p>设备索引不应直接等同于 Linux 的 <code>can0</code> 或 <code>can1</code>。实际使用的 SocketCAN 接口，应根据后端实现和运行配置确认。</p><h3 id="_5-3-canopen-通信机制" tabindex="-1">5.3 CANopen 通信机制 <a class="header-anchor" href="#_5-3-canopen-通信机制" aria-label="Permalink to &quot;5.3 CANopen 通信机制&quot;">​</a></h3><table tabindex="0"><thead><tr><th>机制</th><th>用途</th></tr></thead><tbody><tr><td>SDO</td><td>读写对象字典，用于参数配置和状态查询</td></tr><tr><td>PDO</td><td>传输目标位置、实际位置、控制字和状态字等过程数据</td></tr><tr><td>NMT</td><td>管理 CANopen 节点的网络状态</td></tr><tr><td>Heartbeat</td><td>监测节点的通信存活状态</td></tr><tr><td>SYNC</td><td>在相应设备和配置支持时，协调同步通信</td></tr></tbody></table><p>需要注意：</p><ul><li>PDO 本身不保证周期同步。</li><li>SYNC 机制需要主站、驱动器及相关通信配置共同支持。</li><li>Heartbeat 正常不等于驱动器已经允许运动。</li><li>CAN 通信正常不等于机械运动正常。</li><li>周期同步能力还受主机调度、USB-CAN 传输、总线负载及驱动器实现影响。</li></ul><h3 id="_5-4-位置指令发送" tabindex="-1">5.4 位置指令发送 <a class="header-anchor" href="#_5-4-位置指令发送" aria-label="Permalink to &quot;5.4 位置指令发送&quot;">​</a></h3><p>当前实现使用以下接口及配置：</p><table tabindex="0"><thead><tr><th>项目</th><th>当前描述</th></tr></thead><tbody><tr><td>发送接口</td><td><code>harmonic_writeCanData()</code></td></tr><tr><td>CAN 标识符</td><td><code>0x200 + id</code></td></tr><tr><td>对应通信对象</td><td>RPDO1</td></tr><tr><td>目标位置对象</td><td><code>0x607A</code></td></tr></tbody></table><p><code>0x607A</code> 是 CiA 402 目标位置对象。它是否通过 RPDO1 传输，取决于驱动器实际 PDO 映射。</p><p>因此，项目验证时应确认：</p><ol><li>CAN 标识符与节点地址配置一致。</li><li>PDO 映射包含所需的目标位置和控制数据。</li><li>报文长度、数据布局、字节序及数据类型正确。</li><li>目标位置采用驱动器实际支持的位置单位。</li><li>发送周期与驱动器运行模式相匹配。</li></ol><p>不能仅凭 CAN 标识符或接口调用成功，就认定目标位置已被驱动器正确接受。</p><h3 id="_5-5-cia-402-驱动器状态机" tabindex="-1">5.5 CiA 402 驱动器状态机 <a class="header-anchor" href="#_5-5-cia-402-驱动器状态机" aria-label="Permalink to &quot;5.5 CiA 402 驱动器状态机&quot;">​</a></h3><p>CiA 402 定义了驱动器状态机、控制对象及运动控制模式。驱动器需要进入正确状态后，才能执行相应的运动控制。</p><p>常见对象如下：</p><table tabindex="0"><thead><tr><th>索引</th><th>对象名称</th><th>作用</th></tr></thead><tbody><tr><td><code>0x6040</code></td><td>Controlword</td><td>控制字，用于请求驱动器状态转换</td></tr><tr><td><code>0x6041</code></td><td>Statusword</td><td>状态字，用于读取驱动器当前状态</td></tr><tr><td><code>0x6060</code></td><td>Modes of operation</td><td>目标操作模式</td></tr><tr><td><code>0x6061</code></td><td>Modes of operation display</td><td>当前操作模式显示</td></tr><tr><td><code>0x607A</code></td><td>Target position</td><td>目标位置</td></tr><tr><td><code>0x6064</code></td><td>Position actual value</td><td>实际位置</td></tr></tbody></table><p>典型初始化和启动流程：</p><ol><li>初始化 CANopen 通信。</li><li>检查节点通信状态。</li><li>读取驱动器状态字并检查故障。</li><li>按照 CiA 402 状态转换规则发送控制字。</li><li>确认驱动器进入允许运行的状态。</li><li>设置操作模式，并确认模式显示值。</li><li>按照模式要求发送目标位置。</li><li>持续监测状态字、实际位置及故障信息。</li></ol><p><strong>重要区别：</strong> CANopen NMT 网络状态与 CiA 402 驱动器状态是两个不同的状态体系。节点进入 NMT Operational，不代表驱动器已经进入 Operation enabled。</p><hr><h2 id="_6-csp-周期同步位置控制" tabindex="-1">6. CSP 周期同步位置控制 <a class="header-anchor" href="#_6-csp-周期同步位置控制" aria-label="Permalink to &quot;6. CSP 周期同步位置控制&quot;">​</a></h2><h3 id="_6-1-控制原理" tabindex="-1">6.1 控制原理 <a class="header-anchor" href="#_6-1-控制原理" aria-label="Permalink to &quot;6.1 控制原理&quot;">​</a></h3><p>CSP（Cyclic Synchronous Position，周期同步位置模式）是一种由主控制器周期性更新目标位置、由驱动器执行位置控制的运行模式。</p><p>主控制器负责计算参考位置并按照控制周期发送目标；驱动器根据目标位置和内部反馈执行相应的控制。具体的速度、加速度及电流控制由驱动器内部实现及配置决定。</p><h3 id="_6-2-csp-控制链路" tabindex="-1">6.2 CSP 控制链路 <a class="header-anchor" href="#_6-2-csp-控制链路" aria-label="Permalink to &quot;6.2 CSP 控制链路&quot;">​</a></h3>`,77)),(e(),i(E,null,{default:a(()=>[s(l,{id:"mermaid-938",class:"mermaid",graph:"sequenceDiagram%0A%20%20%20%20participant%20M%20as%20%E8%BF%90%E5%8A%A8%E6%8E%A7%E5%88%B6%E5%99%A8%0A%20%20%20%20participant%20T%20as%20%E8%BD%A8%E8%BF%B9%E8%A7%84%E5%88%92%E4%B8%8E%E5%85%B3%E8%8A%82%E6%98%A0%E5%B0%84%0A%20%20%20%20participant%20A%20as%20%E7%94%B5%E6%9C%BA%E6%8E%A7%E5%88%B6%20API%0A%20%20%20%20participant%20P%20as%20CANopen%20%E5%8D%8F%E8%AE%AE%E5%BA%93%0A%20%20%20%20participant%20C%20as%20CANable%20%2F%20SocketCAN%0A%20%20%20%20participant%20D%20as%20CSP%20%E4%BC%BA%E6%9C%8D%E9%A9%B1%E5%8A%A8%E5%99%A8%0A%20%20%20%20participant%20E%20as%20%E7%94%B5%E6%9C%BA%E4%B8%8E%E5%85%B3%E8%8A%82%0A%0A%20%20%20%20M-%3E%3ET%3A%20%E6%8F%90%E4%BE%9B%E7%9B%AE%E6%A0%87%E4%BD%8D%E7%BD%AE%E4%B8%8E%E5%8A%A8%E4%BD%9C%E6%97%B6%E9%95%BF%0A%20%20%20%20T--%3E%3EM%3A%20%E8%BF%94%E5%9B%9E%E5%BD%93%E5%89%8D%E5%91%A8%E6%9C%9F%E5%8F%82%E8%80%83%E4%BD%8D%E7%BD%AE%0A%20%20%20%20M-%3E%3EA%3A%20%E6%8F%90%E4%BA%A4%E7%9B%AE%E6%A0%87%E7%94%B5%E6%9C%BA%E4%BD%8D%E7%BD%AE%0A%20%20%20%20A-%3E%3EP%3A%20%E8%B0%83%E7%94%A8%E7%94%B5%E6%9C%BA%E6%8E%A7%E5%88%B6%E6%8E%A5%E5%8F%A3%0A%20%20%20%20P-%3E%3EC%3A%20%E5%8F%91%E9%80%81%20CANopen%20%E8%BF%87%E7%A8%8B%E6%95%B0%E6%8D%AE%0A%20%20%20%20C-%3E%3ED%3A%20%E4%BC%A0%E8%BE%93%E7%9B%AE%E6%A0%87%E4%BD%8D%E7%BD%AE%E4%B8%8E%E6%8E%A7%E5%88%B6%E6%95%B0%E6%8D%AE%0A%20%20%20%20D-%3E%3EE%3A%20%E6%89%A7%E8%A1%8C%E5%86%85%E9%83%A8%E4%BD%8D%E7%BD%AE%E6%8E%A7%E5%88%B6%0A%20%20%20%20E--%3E%3ED%3A%20%E6%9C%BA%E6%A2%B0%E4%B8%8E%E7%BC%96%E7%A0%81%E5%99%A8%E5%8F%8D%E9%A6%88%0A%20%20%20%20D--%3E%3EC%3A%20%E8%BF%94%E5%9B%9E%E5%AE%9E%E9%99%85%E4%BD%8D%E7%BD%AE%E4%B8%8E%E7%8A%B6%E6%80%81%0A%20%20%20%20C--%3E%3EP%3A%20%E6%8E%A5%E6%94%B6%20CAN%20%E6%95%B0%E6%8D%AE%0A%20%20%20%20P--%3E%3EA%3A%20%E8%A7%A3%E6%9E%90%E5%AE%9E%E9%99%85%E4%BD%8D%E7%BD%AE%E4%B8%8E%E7%8A%B6%E6%80%81%0A%20%20%20%20A--%3E%3EM%3A%20%E8%BF%94%E5%9B%9E%E5%8F%8D%E9%A6%88%E4%BF%A1%E6%81%AF%0A%20%20%20%20M-%3E%3EM%3A%20%E8%AE%A1%E7%AE%97%E8%AF%AF%E5%B7%AE%E5%B9%B6%E5%88%A4%E6%96%AD%E6%89%A7%E8%A1%8C%E7%8A%B6%E6%80%81%0A"})]),fallback:a(()=>[...t[2]||(t[2]=[d(" Loading... ",-1)])]),_:1})),t[6]||(t[6]=n(`<h3 id="_6-3-csp-实施要求" tabindex="-1">6.3 CSP 实施要求 <a class="header-anchor" href="#_6-3-csp-实施要求" aria-label="Permalink to &quot;6.3 CSP 实施要求&quot;">​</a></h3><p>启用 CSP 前，应确认：</p><ul><li>驱动器支持 CSP，且当前运行模式配置正确。</li><li>驱动器已经进入允许运行的状态。</li><li>目标位置与实际位置使用一致的单位和符号约定。</li><li>PDO 映射与目标数据格式正确。</li><li>主站更新周期满足驱动器要求。</li><li>通信延迟、周期抖动及总线负载在允许范围内。</li><li>多轴运动具有满足需求的同步机制。</li><li>通信中断、驱动器故障及目标丢失时具有明确的处置策略。</li></ul><p>CSP 是驱动器运行模式，不等于整个系统天然具备硬实时能力。系统的实际同步性能取决于主站调度、通信链路和驱动器实现。</p><hr><h2 id="_7-状态反馈与动作完成判定" tabindex="-1">7. 状态反馈与动作完成判定 <a class="header-anchor" href="#_7-状态反馈与动作完成判定" aria-label="Permalink to &quot;7. 状态反馈与动作完成判定&quot;">​</a></h2><h3 id="_7-1-反馈数据" tabindex="-1">7.1 反馈数据 <a class="header-anchor" href="#_7-1-反馈数据" aria-label="Permalink to &quot;7.1 反馈数据&quot;">​</a></h3><p>建议统一采集以下信息：</p><table tabindex="0"><thead><tr><th>数据类型</th><th>主要用途</th></tr></thead><tbody><tr><td>目标位置</td><td>判断当前控制器期望状态</td></tr><tr><td>实际位置</td><td>判断电机与关节的实际运动状态</td></tr><tr><td>位置误差</td><td>判断跟踪偏差</td></tr><tr><td>实际速度（如可用）</td><td>判断运动是否趋于停止</td></tr><tr><td>驱动器状态字</td><td>判断驱动器是否就绪、允许运行或发生故障</td></tr><tr><td>当前操作模式</td><td>确认驱动器实际运行模式</td></tr><tr><td>通信状态</td><td>判断节点及通信链路是否正常</td></tr><tr><td>故障信息</td><td>支持诊断和异常处理</td></tr></tbody></table><p>位置误差定义为：</p><p>$$ e(t)=q_{\\text{target}}(t)-q_{\\text{actual}}(t) $$</p><p>目标位置与实际位置必须处于同一坐标系和单位体系中，才能进行有效比较。</p><h3 id="_7-2-动作完成条件" tabindex="-1">7.2 动作完成条件 <a class="header-anchor" href="#_7-2-动作完成条件" aria-label="Permalink to &quot;7.2 动作完成条件&quot;">​</a></h3><p>建议结合以下条件判断动作是否完成：</p><ul><li>实际位置与最终目标位置的误差进入允许范围。</li><li>实际速度低于停止阈值（若可获取）。</li><li>驱动器处于正常且允许的状态。</li><li>上述条件持续满足指定时间。</li><li>未发生通信故障、驱动器故障或执行超时。</li></ul><p>单次位置接近目标并不足以确认动作完成。对于存在机械振动、回弹或负载扰动的关节，应考虑稳定时间和反馈有效性。</p><h3 id="_7-3-执行状态的区分" tabindex="-1">7.3 执行状态的区分 <a class="header-anchor" href="#_7-3-执行状态的区分" aria-label="Permalink to &quot;7.3 执行状态的区分&quot;">​</a></h3><p>需要严格区分三个阶段：</p><ol><li><strong>命令发送成功</strong>：主机侧完成了相应的发送操作。</li><li><strong>驱动器接受并执行命令</strong>：驱动器处于适当状态，并按配置处理目标。</li><li><strong>实际运动完成</strong>：实际位置和运动状态满足完成判定条件。</li></ol><p>这三个阶段并不等价。上层动作接口应根据实际反馈返回执行结果，而不是仅依据底层发送函数的返回值判断成功。</p><hr><h2 id="_8-故障处理与安全边界" tabindex="-1">8. 故障处理与安全边界 <a class="header-anchor" href="#_8-故障处理与安全边界" aria-label="Permalink to &quot;8. 故障处理与安全边界&quot;">​</a></h2><h3 id="_8-1-异常处理策略" tabindex="-1">8.1 异常处理策略 <a class="header-anchor" href="#_8-1-异常处理策略" aria-label="Permalink to &quot;8.1 异常处理策略&quot;">​</a></h3><table tabindex="0"><thead><tr><th>异常类型</th><th>建议处理原则</th></tr></thead><tbody><tr><td>目标角度超限</td><td>拒绝请求，或按照明确的限幅策略处理</td></tr><tr><td>驱动器未就绪</td><td>禁止启动运动，并记录状态原因</td></tr><tr><td>CAN 通信中断</td><td>停止依赖无效反馈，并执行预定义故障策略</td></tr><tr><td>反馈数据异常</td><td>标记数据无效，避免使用错误状态继续控制</td></tr><tr><td>动作执行超时</td><td>结束任务并进入异常处理流程</td></tr><tr><td>驱动器故障</td><td>读取故障信息，根据设备要求执行故障处理</td></tr><tr><td>用户取消动作</td><td>根据当前状态执行受控停止，并确认结果</td></tr><tr><td>急停请求</td><td>触发系统规定的安全机制</td></tr></tbody></table><p>具体处置动作应根据机械负载、驱动器能力及整机风险评估确定，不应将所有故障统一处理为简单的停止发送。</p><h3 id="_8-2-停止机制的区别" tabindex="-1">8.2 停止机制的区别 <a class="header-anchor" href="#_8-2-停止机制的区别" aria-label="Permalink to &quot;8.2 停止机制的区别&quot;">​</a></h3><table tabindex="0"><thead><tr><th>停止方式</th><th>主要含义</th></tr></thead><tbody><tr><td>普通软件停止</td><td>应用层停止当前动作或生成停止轨迹</td></tr><tr><td>CiA 402 Quick Stop</td><td>根据驱动器配置执行快速停止相关状态转换</td></tr><tr><td>硬件急停</td><td>由整机安全设计规定的急停机制触发</td></tr><tr><td>STO（Safe Torque Off）</td><td>由具备相应安全能力的硬件及系统实现的安全转矩关闭功能</td></tr></tbody></table><p>普通软件停止、Quick Stop、硬件急停及 STO 不能相互替代。尤其是通信中断或主机软件失效时，不能仅依赖普通应用程序发送停止指令来保证安全。</p><hr><h2 id="_9-软件模块组织建议" tabindex="-1">9. 软件模块组织建议 <a class="header-anchor" href="#_9-软件模块组织建议" aria-label="Permalink to &quot;9. 软件模块组织建议&quot;">​</a></h2><p>建议按照职责组织控制软件，逻辑结构如下：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>motion_control/</span></span>
<span class="line"><span>├── controller/</span></span>
<span class="line"><span>│   └── motion_controller</span></span>
<span class="line"><span>├── trajectory/</span></span>
<span class="line"><span>│   └── trajectory_planner</span></span>
<span class="line"><span>├── kinematics/</span></span>
<span class="line"><span>│   ├── joint_mapping</span></span>
<span class="line"><span>│   └── encoder_conversion</span></span>
<span class="line"><span>├── hardware/</span></span>
<span class="line"><span>│   └── servo_motor_api</span></span>
<span class="line"><span>├── protocols/</span></span>
<span class="line"><span>│   └── harmonic_canopen</span></span>
<span class="line"><span>├── feedback/</span></span>
<span class="line"><span>│   └── state_monitor</span></span>
<span class="line"><span>├── safety/</span></span>
<span class="line"><span>│   └── fault_handler</span></span>
<span class="line"><span>└── config/</span></span>
<span class="line"><span>    ├── motor_config</span></span>
<span class="line"><span>    └── joint_limits</span></span></code></pre></div><p>模块说明：</p><ul><li><code>controller</code>：管理动作请求、执行状态及任务生命周期。</li><li><code>trajectory</code>：生成参考位置轨迹，并检查运动约束。</li><li><code>kinematics</code>：处理关节与电机之间的映射。</li><li><code>hardware</code>：提供统一的电机操作接口。</li><li><code>protocols</code>：封装 CANopen 通信和驱动器控制。</li><li><code>feedback</code>：维护实际位置、状态及执行完成判定所需的信息。</li><li><code>safety</code>：处理故障策略、停止请求和异常状态。</li><li><code>config</code>：集中管理电机参数、减速比、零点和关节限位。</li></ul><p>以上为逻辑模块划分，不要求与现有源码文件或动态库一一对应。实施时应优先复用现有代码，避免为了形式上的分层增加不必要的抽象。</p><hr><h2 id="_10-关键设计约束与验证清单" tabindex="-1">10. 关键设计约束与验证清单 <a class="header-anchor" href="#_10-关键设计约束与验证清单" aria-label="Permalink to &quot;10. 关键设计约束与验证清单&quot;">​</a></h2><p>在系统集成和故障排查过程中，建议重点验证以下项目。</p><table tabindex="0"><thead><tr><th>检查项</th><th>验证目标</th></tr></thead><tbody><tr><td>初始化</td><td>设备、波特率、节点地址与通信接口配置正确</td></tr><tr><td>驱动器状态</td><td>状态字及控制字转换符合 CiA 402 要求</td></tr><tr><td>操作模式</td><td>驱动器实际运行模式与控制器预期一致</td></tr><tr><td>位置单位</td><td>关节、电机和驱动器的位置换算一致</td></tr><tr><td>PDO 配置</td><td>CAN 标识符、映射对象、数据布局及长度正确</td></tr><tr><td>轨迹约束</td><td>目标轨迹满足位置、速度和加速度限制</td></tr><tr><td>周期性能</td><td>指令更新周期和通信抖动满足驱动器要求</td></tr><tr><td>反馈有效性</td><td>实际位置、状态和故障信息能够正确解析</td></tr><tr><td>完成判定</td><td>不以命令发送成功代替实际动作完成</td></tr><tr><td>异常处理</td><td>通信中断、执行超时及驱动器故障均有明确策略</td></tr><tr><td>安全功能</td><td>急停及 STO 等功能符合整机安全设计要求</td></tr></tbody></table><hr><h2 id="_11-总结" tabindex="-1">11. 总结 <a class="header-anchor" href="#_11-总结" aria-label="Permalink to &quot;11. 总结&quot;">​</a></h2><p>机器人运动控制系统通过分层架构，将上层动作请求转换为驱动器可执行的位置目标，并通过反馈信息完成执行状态监测。</p><p>其核心链路为：</p><p><strong>动作请求 → 运动控制 → 轨迹规划 → 关节映射 → 电机控制 API → CANopen 协议处理 → CANable / SocketCAN → CSP 伺服驱动器 → 电机执行。</strong></p><p>反馈信息沿相反方向返回，用于位置误差计算、状态监测、动作完成判定和故障处理。</p><p>其中，运动控制模块负责动作生命周期与执行策略，轨迹规划模块负责生成参考位置，关节映射模块负责坐标和单位转换，<code>libeu_harmonic.so</code> 负责 CANopen 协议及驱动器控制，<code>libeu_canable.so</code> 负责底层设备通信，伺服驱动器负责实际的位置控制。</p><p>整个系统的可靠性不仅取决于指令能否发送，还取决于状态机配置、位置单位一致性、通信周期、反馈有效性和安全机制是否经过完整验证。</p>`,47))])}const m=r(A,[["render",c]]);export{D as __pageData,m as default};
